public class ThreadDumpExample {
    public static void main(String[] args) {
        Thread t = new Thread(() -> {
            synchronized (lock) {
                try { Thread.sleep(5000); } catch (InterruptedException e) {}
            }
        });
        t.start();
        synchronized (lock) {
            System.out.println("Main acquired lock");
        }
    }
}
